const rawItem = $input.item.json;
const data = (rawItem && typeof rawItem.output === 'object' && rawItem.output !== null)
  ? rawItem.output
  : (rawItem || {});

function parseNumber(val) {
  if (typeof val === 'number') return val;
  if (!val) return null;
  const cleanStr = String(val).replace(/[^0-9.-]+/g, '');
  const num = parseFloat(cleanStr);
  return isNaN(num) ? null : num;
}

function parseAndNormalizeDate(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return { valid: false, formatted: null, dateObj: null };
  const trimmed = dateStr.trim();

  const dmyMatch = trimmed.match(/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/);
  if (dmyMatch) {
    const day = parseInt(dmyMatch[1], 10);
    const month = parseInt(dmyMatch[2], 10);
    const year = parseInt(dmyMatch[3], 10);
    const d = new Date(year, month - 1, day);
    if (d.getFullYear() === year && d.getMonth() === month - 1 && d.getDate() === day) {
      const formatted = `${String(day).padStart(2, '0')}.${String(month).padStart(2, '0')}.${year}`;
      return { valid: true, formatted, dateObj: d };
    }
  }

  const ymdMatch = trimmed.match(/^(\d{4})[./-](\d{1,2})[./-](\d{1,2})$/);
  if (ymdMatch) {
    const year = parseInt(ymdMatch[1], 10);
    const month = parseInt(ymdMatch[2], 10);
    const day = parseInt(ymdMatch[3], 10);
    const d = new Date(year, month - 1, day);
    if (d.getFullYear() === year && d.getMonth() === month - 1 && d.getDate() === day) {
      const formatted = `${String(day).padStart(2, '0')}.${String(month).padStart(2, '0')}.${year}`;
      return { valid: true, formatted, dateObj: d };
    }
  }

  const parsed = new Date(trimmed);
  if (!isNaN(parsed.getTime())) {
    const day = String(parsed.getDate()).padStart(2, '0');
    const month = String(parsed.getMonth() + 1).padStart(2, '0');
    const year = parsed.getFullYear();
    return { valid: true, formatted: `${day}.${month}.${year}`, dateObj: parsed };
  }

  return { valid: false, formatted: trimmed, dateObj: null };
}

function formatLineItems(items) {
  if (!items) return '';
  let parsed = items;
  if (typeof items === 'string') {
    try {
      parsed = JSON.parse(items);
    } catch (e) {
      return items.trim();
    }
  }
  if (Array.isArray(parsed)) {
    return parsed.map(item => {
      const desc = item.description || item.name || item.item || 'Item';
      const qty = item.quantity !== undefined ? item.quantity : item.qty;
      const unitPrice = item.unit_price !== undefined ? item.unit_price : item.price;
      const total = item.total !== undefined ? item.total : item.amount;

      let part = desc;
      if (qty !== undefined && unitPrice !== undefined) {
        part += ` (${qty}x ${unitPrice})`;
      } else if (qty !== undefined) {
        part += ` (Qty: ${qty})`;
      }
      if (total !== undefined) {
        part += ` = ${total}`;
      }
      return part;
    }).join('; ');
  }
  return String(items);
}

const errors = [];
const warnings = [];

if (!data.invoice_number || String(data.invoice_number).trim() === '') {
  errors.push('Missing or empty required field: invoice_number');
}

const invDateResult = parseAndNormalizeDate(data.invoice_date);
if (!invDateResult.valid) {
  errors.push(`Invalid or missing invoice_date: "${data.invoice_date}". Expected valid date.`);
}

if (!data.vendor_name || String(data.vendor_name).trim() === '') {
  errors.push('Missing or empty required field: vendor_name');
}
if (!data.customer_name || String(data.customer_name).trim() === '') {
  warnings.push('Missing customer_name');
}
if (!data.currency || String(data.currency).trim() === '') {
  errors.push('Missing currency code');
}

const subtotal = parseNumber(data.subtotal);
const vatRate = parseNumber(data.vat_rate);
const vatAmount = parseNumber(data.vat_amount);
const totalAmount = parseNumber(data.total_amount);

if (totalAmount === null || totalAmount <= 0) {
  errors.push(`Invalid total_amount: "${data.total_amount}". Must be a positive number.`);
}
if (subtotal === null || subtotal <= 0) {
  errors.push(`Invalid subtotal: "${data.subtotal}". Must be a positive number.`);
}
if (vatAmount === null && vatRate !== null && vatRate > 0) {
  errors.push('Missing vat_amount when vat_rate is specified.');
}

let dueDateResult = { valid: false, formatted: null, dateObj: null };
if (data.due_date) {
  dueDateResult = parseAndNormalizeDate(data.due_date);
  if (!dueDateResult.valid) {
    warnings.push(`due_date "${data.due_date}" could not be validated.`);
  } else if (invDateResult.valid && dueDateResult.dateObj < invDateResult.dateObj) {
    errors.push(`Date inconsistency: due_date (${dueDateResult.formatted}) is earlier than invoice_date (${invDateResult.formatted}).`);
  }
}

const ROUNDING_TOLERANCE = 0.05;
if (subtotal !== null && vatRate !== null && vatAmount !== null) {
  const expectedVat = Math.round(subtotal * (vatRate / 100) * 100) / 100;
  const diff = Math.abs(expectedVat - vatAmount);
  if (diff > ROUNDING_TOLERANCE) {
    errors.push(`VAT calculation mismatch: expected ~${expectedVat.toFixed(2)} (${vatRate}% of ${subtotal.toFixed(2)}), but found ${vatAmount.toFixed(2)} (diff: ${diff.toFixed(2)}).`);
  }
}

if (subtotal !== null && totalAmount !== null) {
  const actualVat = vatAmount !== null ? vatAmount : 0;
  const expectedTotal = Math.round((subtotal + actualVat) * 100) / 100;
  const totalDiff = Math.abs(expectedTotal - totalAmount);
  if (totalDiff > ROUNDING_TOLERANCE) {
    errors.push(`Total calculation mismatch: expected ~${expectedTotal.toFixed(2)} (subtotal ${subtotal.toFixed(2)} + VAT ${actualVat.toFixed(2)}), but found ${totalAmount.toFixed(2)} (diff: ${totalDiff.toFixed(2)}).`);
  }
}

const isValid = errors.length === 0;
const validationStatus = isValid ? (warnings.length > 0 ? 'PASSED_WITH_WARNINGS' : 'PASSED') : 'FAILED_CHECKS';

const validationSummary = isValid
  ? `[VALIDATION PASSED] All required fields, calculations (VAT and Total), and dates verified successfully.${warnings.length > 0 ? ' Warnings: ' + warnings.join('; ') : ''}`
  : `[VALIDATION FAILED] Encountered ${errors.length} error(s): ${errors.join('; ')}.${warnings.length > 0 ? ' Warnings: ' + warnings.join('; ') : ''}`;

const formattedLineItems = formatLineItems(data.line_items);

return {
  json: {
    invoice_number: data.invoice_number ? String(data.invoice_number).trim() : null,
    invoice_date: invDateResult.formatted || data.invoice_date,
    due_date: dueDateResult.formatted || data.due_date || null,
    vendor_name: data.vendor_name ? String(data.vendor_name).trim() : null,
    vendor_vat_id: data.vendor_vat_id ? String(data.vendor_vat_id).trim() : null,
    customer_name: data.customer_name ? String(data.customer_name).trim() : null,
    customer_vat_id: data.customer_vat_id ? String(data.customer_vat_id).trim() : null,
    line_items: formattedLineItems,
    line_items_raw: data.line_items || null,
    subtotal: subtotal !== null ? subtotal : data.subtotal,
    vat_rate: vatRate !== null ? vatRate : data.vat_rate,
    vat_amount: vatAmount !== null ? vatAmount : data.vat_amount,
    total_amount: totalAmount !== null ? totalAmount : data.total_amount,
    currency: data.currency ? String(data.currency).trim().toUpperCase() : null,
    iban: data.iban ? String(data.iban).trim() : null,
    payment_terms: data.payment_terms || null,
    is_valid: isValid,
    validation_status: validationStatus,
    validation_errors: errors,
    validation_warnings: warnings,
    validation_summary: validationSummary
  }
};
